import {computeHMAC} from './plus-crypto.mjs';
import {form,field,text,area,select as sel,e,n,bytes,result,error,outputText,download} from '../ui.mjs';
import {uploadHTML,bindUpload} from '../media.mjs';
import {subnet,permissionMode,harSummary,sanitizeHAR} from './plus-core.mjs';
import {table,textFile,exportCSV} from './shared.mjs';
export function setupSecurityPlus(tool,mount,out){
 if(tool.id==='subnet-calculator')return form(mount,[text('cidr','IPv4 address / CIDR','192.0.2.143/27')],v=>{const r=subnet(v.cidr);result(out,{label:'Network',value:r.network+'/'+r.prefix,details:[['Subnet mask',r.mask],['Wildcard mask',r.wildcard],['Full range',r.network+' – '+r.last],['Addresses',n(r.size)],['Host interpretation',r.interpretation],['Host range',r.firstHost+' – '+r.lastHost],['Usable hosts under this interpretation',n(r.usable)],['Broadcast',r.broadcast]],copy:JSON.stringify(r,null,2),note:'IPv4 arithmetic only. No packets are sent and no network configuration is changed.'});},{label:'Calculate subnet'});
 if(tool.id==='chmod-builder')return chmod(mount,out);
 if(tool.id==='hmac-generator')return hmac(mount,out);
 if(tool.id==='har-viewer')return har(mount,out);
}
function chmod(mount,out){mount.innerHTML='<h2>Read, write, execute. Made clearer.</h2><form><div class="permission-grid"><span></span><strong>Read · 4</strong><strong>Write · 2</strong><strong>Execute / search · 1</strong>'+['Owner','Group','Other'].map((name,row)=>'<strong>'+name+'</strong>'+[0,1,2].map(col=>'<label><input type="checkbox" name="b'+(row*3+col)+'" aria-label="'+name+' '+['read','write','execute or search'][col]+'" '+([0,1,3,6].includes(row*3+col)?'checked':'')+'><span class="sr-only">'+name+' '+['read','write','execute'][col]+'</span></label>').join('')).join('')+'</div><div class="form-grid">'+[sel('special','Special mode bits',[['0','None'],['1','Sticky · 1'],['2','Set group ID · 2'],['4','Set user ID · 4'],['3','Setgid + sticky · 3'],['5','Setuid + sticky · 5'],['6','Setuid + setgid · 6'],['7','All special bits · 7']],'0'),sel('kind','Object type',[['file','Regular file'],['directory','Directory']],'file')].map(field).join('')+'</div><div class="form-actions"><button class="btn primary" type="submit">Build mode</button></div></form>';const f=mount.querySelector('form');function render(){const bits=Array.from({length:9},(_,i)=>f.elements['b'+i].checked),r=permissionMode(bits,+f.elements.special.value,f.elements.kind.value==='directory');outputText(out,'chmod '+r.octal+' your-file',[['Symbolic mode',r.symbolic],['Numeric mode',r.octal],['Meaning','Read 4 + write 2 + execute/search 1 for each class']]);out.insertAdjacentHTML('beforeend','<p class="form-note">Illustrative command only. For directories, execute means search/traversal. Special-bit behavior depends on the operating system and object type. No command is executed here.</p>');}f.onsubmit=ev=>{ev.preventDefault();render();};f.onchange=render;render();}
function hmac(mount,out){let disposed=false;form(mount,[area('message','Message','Hello Nepocore'),text('key','Shared key','demo-key','password',true),sel('keyFormat','Key encoding',[['text','UTF-8 text'],['hex','Hexadecimal bytes']],'text'),sel('algorithm','Hash algorithm',['SHA-256','SHA-512'],'SHA-256'),{...text('expected','Expected HMAC hex (optional)','','text',true),required:false}],async v=>{const {hex,verified,messageBytes}=await computeHMAC(v);if(disposed)return;outputText(out,hex,[['Algorithm','HMAC '+v.algorithm],['Message bytes',messageBytes],['Comparison',verified===null?'No reference supplied':verified?'MATCH':'DOES NOT MATCH']]);},{label:'Generate / verify HMAC',note:'The sample key is not secret. Keys are not saved by this tool. HMAC authenticates a message; it does not encrypt it.'});return()=>{disposed=true;};}
function har(mount,out){let current,disposed=false;mount.innerHTML='<h2>A clearer look at a network log.</h2>'+uploadHTML('.har,.json,application/json',false,'Choose a HAR log','Local HAR / JSON · up to 20 MB')+'<p class="form-note">Logs can contain secrets. URLs are displayed for your inspection, but no request is replayed.</p><button type="button" class="btn secondary small" data-sample>Load a synthetic sample</button><div class="form-grid har-controls">'+[sel('sort','Sort requests',[['time','Slowest first'],['bytes','Largest first'],['order','Original order']],'time'),text('filter','Filter URL or status','')].map(field).join('')+'</div><div class="form-error"></div>';const err=mount.querySelector('.form-error');function render(){if(!current)return;const filter=mount.querySelector('[name=filter]').value.toLowerCase(),sort=mount.querySelector('[name=sort]').value,list=current.entries.filter(x=>(x.url+' '+x.status).toLowerCase().includes(filter)).sort((a,b)=>sort==='order'?a.i-b.i:b[sort]-a[sort]);result(out,{label:'Requests',value:list.length,details:[['Recorded response bytes',bytes(current.totalBytes)],['Sum of request durations',n(current.totalTime/1000)+' s (requests can overlap)']],html:table(['Method','URL','Status','Time','Bytes'],list.slice(0,100).map(x=>[x.method,x.url,x.status,n(x.time)+' ms',bytes(x.bytes)])),note:'First 100 matching rows shown. Reduced exports remove headers, query values, bodies and original timestamps; paths and hostnames can still identify people or systems.'});exportCSV(out,list.map(({i,method,url,status,time,bytes})=>({order:i+1,method,url,status,milliseconds:time,bytes})),'nepocore-har-summary.csv');const b=document.createElement('button');b.type='button';b.className='btn secondary small';b.textContent='Export reduced HAR';b.onclick=()=>download(new Blob([JSON.stringify(sanitizeHAR(current.data),null,2)],{type:'application/json'}),'nepocore-reduced.har');const actions=out.querySelector('.result-actions');(actions||out).append(b);}
 bindUpload(mount,async files=>{try{const file=files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Choose a HAR under 20 MB.');const parsed=harSummary(await file.text());if(disposed)return;current=parsed;err.innerHTML='';render();}catch(ex){if(!disposed)error(err,ex.message);}});mount.querySelector('[data-sample]').onclick=()=>{current=harSummary({log:{entries:[{request:{method:'GET',url:'https://example.com/app.js?token=DEMO'},response:{status:200,bodySize:42000,content:{mimeType:'application/javascript'}},time:125},{request:{method:'GET',url:'https://example.com/image.png'},response:{status:200,bodySize:128000,content:{mimeType:'image/png'}},time:340}]}});render();};mount.querySelector('[name=sort]').onchange=render;mount.querySelector('[name=filter]').oninput=render;return()=>{disposed=true;current=null;};}
